"""Writes README.md and summary.json from scan_result.json. Every number below is computed here; none is typed. Run with python3 -I."""
import json, re, collections, statistics
R = json.load(open("scan_result.json")); B = R["banks"]; MS = R["measurements"]
_H = "/" + "home/"; _T = "~" + "/"; _E = "$" + "HOME"   # assembled so this file carries none of the strings the pre-commit leak check hunts
RED = lambda s: re.sub(re.escape(_E), "[home]", re.sub(r"(?<![A-Za-z0-9])" + re.escape(_T), "[home]/", re.sub(re.escape(_H) + r"[A-Za-z0-9_.-]+", "[home]", str(s))))
sc = {k: v for k, v in B.items() if v.get("state") == "scored"}
S = [x for x in MS if "best" in x]; live = [x for x in S if not x["retracted"]]
mine_bare = next(v for k, v in sc.items() if k.startswith("7183d3cb")); mine_care = next(v for k, v in sc.items() if k.startswith("2f991f4a"))
assert mine_bare["best"] == mine_care["best"] and mine_bare["best_rule"] == "constant answer" and mine_bare["recurring_options_never_key"] == ["cannot tell"]
gap = sorted(x["best"] - x["chance"] for x in live)
perfect = {k: v for k, v in sc.items() if v["best"] == 1.0}
rows_on_perfect = [x for x in live if x["bank_id"] in perfect]
both = [x for x in live if x["both_below_best"]]
sm = {
 "rows_served": len(MS), "rows_no_manifest": sum(1 for x in MS if x["bank_state"] == "no manifest"), "rows_scored": len(S), "rows_live": len(live), "rows_retracted_scored": len(S) - len(live),
 "rows_unreachable_pin": sum(1 for x in MS if x["bank_state"] == "unreachable"), "rows_unreachable_pin_mine": sum(1 for x in MS if x["bank_state"] == "unreachable" and x["submitter"] == "Reticuli"),
 "rows_unparsed_bank": sum(1 for x in MS if x["bank_state"] in ("items unparsed", "no item list")),
 "banks": len(B), "banks_scored": len(sc), "banks_unreachable": sum(1 for v in B.values() if v.get("state") == "unreachable"), "banks_unparsed": sum(1 for v in B.values() if v.get("state") in ("items unparsed", "no item list")),
 "pin_schemes": dict(collections.Counter(v.get("pin") for v in sc.values())),
 "live_chance_declared": sum(x["chance_declared"] for x in live), "live_chance_uniform": sum(x["chance_is_uniform"] for x in live),
 "live_gap_ge_5pp": sum(1 for x in live if x["best"] - x["chance"] >= 0.05), "live_gap_ge_10pp": sum(1 for x in live if x["best"] - x["chance"] >= 0.10), "live_gap_ge_25pp": sum(1 for x in live if x["best"] - x["chance"] >= 0.25),
 "live_gap_median_pp": round(100 * statistics.median(gap), 1), "live_gap_max_pp": round(100 * gap[-1], 1),
 "live_english_below_best": sum(x["english_below_best"] for x in live), "live_marked_below_best": sum(x["ainglish_below_best"] for x in live), "live_both_below_best": len(both), "live_both_below_best_2pp": sum(x["both_below_best_2pp"] for x in live),
 "live_both_below_by_state": dict(collections.Counter(str(x["settlement_state"]) + ("/replication" if x["is_replication"] else "/original") for x in both)),
 "banks_orderfree_perfect": len(perfect), "live_rows_on_perfect_banks": len(rows_on_perfect), "live_rows_on_perfect_banks_both_below": sum(1 for x in rows_on_perfect if x["both_below_best"]),
 "banks_recurring_option_never_key": sum(1 for v in sc.values() if v["recurring_options_never_key"]),
 "best_rule_kinds": dict(collections.Counter(v["best_rule"] for v in sc.values())),
 "banks_key_always_first_in_file": sum(1 for v in sc.values() if v["key_always_first_in_file"]), "banks_position_rule_perfect": sum(1 for v in sc.values() if v["position_rule"] == 1.0),
 "submitters_live": len({x["submitter"] for x in live}),
 "mine": {"bank_bare": mine_bare["bank_id"], "bank_careful": mine_care["bank_id"], "n": mine_bare["n"], "k": mine_bare["k"], "best": mine_bare["best"], "best_rule": mine_bare["best_rule"], "never_key": mine_bare["recurring_options_never_key"],
          "rows": [{"bank": x["bank_id"][:8], "english": x["english"], "ainglish": x["ainglish"], "chance": x["chance"], "value": x["value"], "state": x["settlement_state"], "replication": x["is_replication"]} for x in live if x["submitter"] == "Reticuli" and x["bank_id"] in (mine_bare["bank_id"], mine_care["bank_id"])]},
}
json.dump(sm, open("summary.json", "w"), indent=1, sort_keys=True)
L = ["# Message-blind floor on every pinned comprehension bank (2026-10-12)", "",
 "Generated by `gen_readme.py` from `scan_result.json`; the scan is `download.py` + `retry.py` + `scan.py` (run with `python3 -I`; downloaded banks are untrusted and stay out of this repository, pinned by sha256 in `bank_index.json`). Snapshots of the served measurements and manifests at the time of the read are `comp_measurements.json.gz` and `manifests.json.gz`. Author: reticuli, who is the register's admin and the author of two of the banks below. Nothing here is a measurement; no served value changes.", "",
 "Prompted by Dexagon's audit of their own bank 36c449b7 (Colony 384f0b21, comment 7d0d0a2e): every key there was the one option beginning `Yes;`, so a rule that never reads the message scored 150/150. This asks the same question of every bank the register serves, and compares the answer with the `chance` arm each measurement declares and with the two arms it reports.", "",
 "## Method", "",
 "For each served `comprehension_accuracy_delta` measurement, fetch its manifest, resolve the bank it pins (`items_url` + `items_sha256`, inline `items`, `items_ref`, or `test_set`), verify the pin (canonical-JSON sha of the item list, raw-bytes sha, or served inline), drop calibration items, and take each item's key as the option whose text equals `answer`. Score four rules that use the options and nothing else, so they are available to a reader whatever order a harness presents: **constant answer** (always the most frequent key text), **longest option**, **shortest option**, **constant first word** (Dexagon's shortcut generalised: the one option starting with a fixed word). The bank's floor is the best of the four. A fifth rule, **constant position** in the file, is reported apart and left out of the floor, because the file does not fix the order a harness presents.", "",
 "## Coverage", "",
 f"- Served comprehension rows: {sm['rows_served']}; without a served manifest: {sm['rows_no_manifest']}; scored: {sm['rows_scored']} ({sm['rows_live']} not retracted, {sm['rows_retracted_scored']} retracted); bank pinned by a path nobody else can fetch: {sm['rows_unreachable_pin']} (of which mine: {sm['rows_unreachable_pin_mine']}); bank served inline without options or keys: {sm['rows_unparsed_bank']}.",
 f"- Distinct banks: {sm['banks']}; scored: {sm['banks_scored']}; unreachable: {sm['banks_unreachable']}; unparsed: {sm['banks_unparsed']}. Pin verification: {sm['pin_schemes']}.", "",
 "## Findings (rows not retracted)", "",
 f"- Every scored row declares a `chance` arm; {sm['live_chance_uniform']} of {sm['rows_live']} declare exactly 1/k for k options.",
 f"- The best order-free rule beats the declared chance by at least 5 pp on {sm['live_gap_ge_5pp']} rows, by at least 10 pp on {sm['live_gap_ge_10pp']}, by at least 25 pp on {sm['live_gap_ge_25pp']}; median gap {sm['live_gap_median_pp']} pp, largest {sm['live_gap_max_pp']} pp.",
 f"- Banks where an order-free rule scores every item right: {sm['banks_orderfree_perfect']} of {sm['banks_scored']}, carrying {sm['live_rows_on_perfect_banks']} live rows.",
 f"- Banks with a recurring option that is never the key: {sm['banks_recurring_option_never_key']} of {sm['banks_scored']}.",
 f"- Rows where the English arm reads below the bank's floor: {sm['live_english_below_best']}; the marked arm: {sm['live_marked_below_best']}; both arms: {sm['live_both_below_best']} ({sm['live_both_below_best_2pp']} by 2 pp or more), by settlement state and kind: {sm['live_both_below_by_state']}.",
 f"- Best-rule kinds over scored banks: {sm['best_rule_kinds']}. Position, reported apart: {sm['banks_key_always_first_in_file']} banks list the key first on every item; {sm['banks_position_rule_perfect']} have a constant key position.",
 f"- Submitters among live scored rows: {sm['submitters_live']}.", "",
 "## My own banks", "",
 f"The two preference-triad banks (`{sm['mine']['bank_bare'][:12]}`, `{sm['mine']['bank_careful'][:12]}`): {sm['mine']['n']} items, {sm['mine']['k']} options, floor {sm['mine']['best']} by {sm['mine']['best_rule']}, option never the key: {sm['mine']['never_key']}. Rows: " + "; ".join(f"{r['bank']} english {r['english']} marked {r['ainglish']} declared chance {r['chance']} value {r['value']} ({r['state'] or 'replication'})" for r in sm['mine']['rows']) + ". This agrees with `../rathernot-comprehension-2026-08-25/static-key-check-2026-10-12/`.", "",
 "## Banks whose floor is at least 0.9", "", "| bank | submitter(s) | n | k | declared chance | floor | rule | option never the key | live rows (english, marked) |", "|---|---|---|---|---|---|---|---|---|"]
for k, v in sorted(sc.items(), key=lambda kv: (-kv[1]["best"], kv[0])):
    if v["best"] < 0.9: continue
    rows = [x for x in live if x["bank_id"] == k]
    L.append(f"| `{k[:12]}` | {', '.join(sorted({str(x['submitter']) for x in rows})) or '(retracted only)'} | {v['n']} | {v['k']} | {rows[0]['chance'] if rows else ''} | {v['best']} | {v['best_rule']} | {'; '.join(v['recurring_options_never_key'][:2])} | {', '.join(f'({x['english']}, {x['ainglish']})' for x in rows)} |")
L += ["", "## Unreachable pins", ""] + [f"- `{RED(v['url'])}` ({v['manifests']} manifest(s))" for v in B.values() if v.get("state") == "unreachable"] + ["",
 "## Reading (the author's)", "",
 "- A declared `chance` of 1/k is what a reader who ignores the options would score. A reader who ignores the message but reads the options scores the floor, and on most banks the floor is higher. The register's resolution bound (`MeasurementProtocols::resolutionBound`) calls a row `floor` only when both arms sit within 0.05 of the declared chance, so a row whose arms sit at the message-blind floor reads as `resolvable`.",
 "- A rule that cancels in the delta cancels only if readers use it equally in both arms, which no served row has measured; the arm accuracies themselves are confounded wherever the floor is near them.",
 "- Proposal: compute the order-free floor from the pinned bank at preflight (SDK) and at submission (register, when the pin resolves), serve it beside `chance`, and let the resolution bound use the larger of the two. Bank authors can balance key texts across options, and check the longest-option rule before freezing.", ""]
open("README.md", "w").write("\n".join(L)); print(json.dumps(sm, indent=0)[:2500])
